contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send Ether to this test contract so it can forward to c and check balances
    receive() external payable {}

    // Drives the contract and asserts the distinguishing property
    // params:
    // - sender: the address used to call withdrawAll (simulated by calling from this contract but we observe owner())
    // - sendAmount: amount of wei to fund C before withdrawal
    // - recipient: address to receive the withdrawn funds
    function run(address recipient, uint256 sendAmount) public payable {
        // Preconditions: this contract must hold enough Ether to fund c
        require(address(this).balance >= sendAmount);
        // fund contract c by sending Ether to its fallback
        payable(address(c)).transfer(sendAmount);

        // Record balances before
        uint256 beforeRecipient = address(recipient).balance;
        uint256 beforeC = address(c).balance;

        // Call withdrawAll from this contract (msg.sender will be this contract)
        c.withdrawAll(recipient);

        // Record balances after
        uint256 afterRecipient = address(recipient).balance;
        uint256 afterC = address(c).balance;

        // The general rule: withdrawAll transfers entire c balance to recipient iff caller equals stored owner
        // We observe whether the transfer happened by checking recipient balance change equals previous c balance
        bool transferHappened = (afterRecipient - beforeRecipient) == beforeC;

        // owner() is public; check if this contract was the owner
        bool callerIsOwner = (c.owner() == address(this));

        // Exactly one assert capturing the property distinguishing P from M:
        // On the original P, transferHappened implies callerIsOwner. On M, transfer can only happen when caller is zero address (impossible here), so property will be violated there.
        assert(transferHappened == callerIsOwner);
    }
}

