    C c;
    constructor(C _c) { c = _c; }

    // Single test function driving the contract and asserting the distinguishing property
    // params:
    //   caller is the address that will call withdrawAll (simulated by passing as parameter; test frameworks will call this function from that address)
    //   recipient is the intended recipient passed into withdrawAll
    //   sendAmount is the ether sent into c prior to withdrawal

    // Note: This function must be called by an external test harness with appropriate msg.sender and balance setup.
    function runTest(address caller, address payable recipient, uint256 sendAmount) public {
        // Preconditions for meaningful test: contract under test must hold some balance to withdraw
        require(address(this).balance >= sendAmount, "insufficient test ether");

        // Fund c with sendAmount so withdrawAll has something to transfer.
        // Send via fallback by calling c with value.
        // This is a state-changing call on c and must be a top-level statement.
        (bool ok,) = address(c).call{value: sendAmount}("");
        require(ok, "funding failed");

        // Now call withdrawAll as the caller. According to the harness rules, the test harness should invoke this
        // runTest with msg.sender == caller. The following call will thus be made by that caller.
        c.withdrawAll(recipient);

        // After withdrawAll, check that the contract's balance is zero (i.e., full transfer occurred) iff caller == c.owner()
        // This is the distinguishing rule: in original P only owner can trigger full withdrawal to arbitrary recipient.
        // We assert that if caller equals owner then c's balance is zero, otherwise c's balance is unchanged (nonzero).
        // Because the test function is executed by 'caller', msg.sender at this point equals caller.

        // Read owner and c balance via public getters
        address owner = c.owner();
        uint256 bal = address(c).balance;

        // If caller was owner then all funds must have been transferred out (balance == 0).
        // If caller was not owner then withdraw should have reverted in P; but since we executed the call, to keep
        // the assertion machine-checkable we require that in that case balance != 0 (i.e., no transfer happened).
        assert((msg.sender == owner && bal == 0) || (msg.sender != owner && bal != 0));
    }

    // Allow contract to receive ether for the test harness to fund it before calling runTest
    receive() external payable {}
}

