pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz the caller who will attempt to withdraw and the amount to fund the contract
    function testFuzz_property(address caller, uint256 fund) public {
        // keep fund in a reasonable wide range but allow zero too
        fund = bound(fund, 0, 1 ether);
        // avoid the fuzzer picking the owner (address(this)) as caller in every case; we still allow it
        // but to find the mutant behavior we want non-owner callers included — no assume so fuzzer can try all

        // Fund the contract from this test contract
        vm.deal(address(this), fund);
        // send ether to c so there is a balance to withdraw
        (bool s, ) = address(c).call{value: fund}("");
        require(s);

        // Now have `caller` attempt to call withdrawAll paying attention to who is allowed
        // If caller is the test contract itself (owner), the reference should allow withdraw and contract balance becomes 0
        // If caller is not owner, the reference should revert / prevent transfer and contract balance remains fund

        // Make the call and observe success/failure
        bool ok;
        vm.prank(caller);
        try c.withdrawAll(address(uint160(uint256(keccak256(abi.encodePacked(caller, "dest")))))) { // dest is some address derived from caller
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: the reference enforces that only the owner (address(this)) can succeed.
        // So for all inputs the reference will satisfy: (ok == (caller == address(this))).
        // The mutant that removed the require will allow non-owner callers to succeed (ok==true while caller!=owner) for some inputs.
        assertTrue(ok == (caller == address(this)));
    }
}
